// =========================================================================
// Node I/O Example Tests
// =========================================================================

// These tests verify individual node behavior against specified examples.
// Each test executes a single node with given inputs and checks outputs.

/// Node example: platform_env - Detects host platform as a string
/// 
/// Tests that node 'platform_env' produces expected outputs for given inputs.
#[test]
fn test_example_platform_env_detects_host_platform_as_a_string() {
    if !guard_test("test_example_platform_env_detects_host_platform_as_a_string", TestClass::Hermetic, FermiCost::S, &["fs", "shell"], &[]) {
    return ();
};
    let dag = crate :: graph :: build_deps_graph().unwrap();
    let inputs = std::collections::HashMap::new();
    let outputs = gunbc_exec::execute_single_node(&dag, "platform_env", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'platform_env' should execute successfully");

    // Check output port 'platform'
    let output_platform = outputs.get("platform").expect("output port 'platform' should exist");
    assert!(output_platform.as_str().is_some(), "expected String for output_platform");
}

/// Node example: prepare_load_manifest - Prepares file read request for deps.toml
/// 
/// Tests that node 'prepare_load_manifest' produces expected outputs for given inputs.
#[test]
fn test_example_prepare_load_manifest_prepares_file_read_request_for_deps_toml() {
    if !guard_test("test_example_prepare_load_manifest_prepares_file_read_request_for_deps_toml", TestClass::Hermetic, FermiCost::S, &["fs", "shell"], &[]) {
    return ();
};
    let dag = crate :: graph :: build_deps_graph().unwrap();
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("manifest_path".to_string(), Value::Str("deps.toml".to_string()));
    let outputs = gunbc_exec::execute_single_node(&dag, "prepare_load_manifest", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'prepare_load_manifest' should execute successfully");

    // Check output port 'manifest_path'
    let output_manifest_path = outputs.get("manifest_path").expect("output port 'manifest_path' should exist");
    assert_eq!(*output_manifest_path, Value::Str("deps.toml".to_string()), "expected exact value");
    // Check output port 'request'
    let output_request = outputs.get("request").expect("output port 'request' should exist");
    assert!(output_request.as_request().is_some(), "expected Request for output_request");
}

