/// Node example: parse_execute_result - Parses install execution result
/// 
/// Tests that node 'parse_execute_result' produces expected outputs for given inputs.
#[test]
fn test_example_parse_execute_result_parses_install_execution_result() {
    if !guard_test("test_example_parse_execute_result_parses_install_execution_result", TestClass::Hermetic, FermiCost::S, &["fs", "shell"], &[]) {
    return ();
};
    let dag = crate :: graph :: build_deps_graph().unwrap();
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("response".to_string(), Value::Response(gunbc_ir::transport::TransportResponse::Shell(gunbc_ir::transport::ShellResponse { exit_code: 0, stdout: "installed
".to_string(), stderr: "".to_string() })));
    inputs.insert("script".to_string(), Value::Str("echo install".to_string()));
    let outputs = gunbc_exec::execute_single_node(&dag, "parse_execute_result", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'parse_execute_result' should execute successfully");

    // Check output port 'executed'
    let output_executed = outputs.get("executed").expect("output port 'executed' should exist");
    assert_eq!(*output_executed, Value::Bool(true), "expected exact value");
    // Check output port 'script'
    let output_script = outputs.get("script").expect("output port 'script' should exist");
    assert_eq!(*output_script, Value::Str("echo install".to_string()), "expected exact value");
    // Check output port 'stderr'
    let output_stderr = outputs.get("stderr").expect("output port 'stderr' should exist");
    assert_eq!(*output_stderr, Value::Str("".to_string()), "expected exact value");
    // Check output port 'stdout'
    let output_stdout = outputs.get("stdout").expect("output port 'stdout' should exist");
    assert_eq!(*output_stdout, Value::Str("installed
".to_string()), "expected exact value");
    // Check output port 'success'
    let output_success = outputs.get("success").expect("output port 'success' should exist");
    assert_eq!(*output_success, Value::Bool(true), "expected exact value");
}

